INSERT INTO customer_satisfaction_surveys (id, title, description, questions, settings, is_active, created_at, updated_at, created_by, csr_name) VALUES (1, 'Customer Satisfaction Evaluation Form', 'On a scale from 1 to 10, One is the lowest level (very dissatisfied), while ten is the highest level (very satisfied), how would you rate the following:', '[{"id":"product-quality","type":"rating","scale":{"max":10,"min":1,"maxLabel":"Very Satisfied","minLabel":"Very Dissatisfied"},"question":"How would you rate the overall quality of our products?","required":true},{"id":"product-quality-comments","type":"textarea","question":"Comments on product quality:","required":false},{"id":"delivery-timeframe","type":"rating","scale":{"max":10,"min":1,"maxLabel":"Very Satisfied","minLabel":"Very Dissatisfied"},"question":"How would you rate the delivery timeframe for our products?","required":true},{"id":"delivery-timeframe-comments","type":"textarea","question":"Comments on delivery timeframe:","required":false},{"id":"customer-service","type":"rating","scale":{"max":10,"min":1,"maxLabel":"Very Satisfied","minLabel":"Very Dissatisfied"},"question":"How would you rate our customer service?","required":true},{"id":"customer-service-comments","type":"textarea","question":"Comments on customer service:","required":false},{"id":"fit-function","type":"rating","scale":{"max":10,"min":1,"maxLabel":"Very Satisfied","minLabel":"Very Dissatisfied"},"question":"How satisfied are you with the overall fit and function of our products?","required":true},{"id":"fit-function-comments","type":"textarea","question":"Comments on fit and function:","required":false},{"id":"recommendation-likelihood","type":"rating","scale":{"max":10,"min":1,"maxLabel":"Very Likely","minLabel":"Highly Unlikely"},"question":"How likely are you to recommend our company and products to others? (1 is Highly Unlikely, 10 is Very Likely)","required":true},{"id":"recommendation-comments","type":"textarea","question":"Comments on recommendation likelihood:","required":false},{"id":"other-products","type":"textarea","question":"What is one other inlet or product you would be interested in seeing us offer?","required":false}]', '{"autoSave":true,"allowAnonymous":false,"showProgressBar":true,"sendEmailReminders":true}', true, '2025-08-27T05:47:57.330Z', '2025-08-27T05:47:57.330Z', NULL, NULL);
